// --- Firebase Initialization ---
let app, db, auth, user;
let initPromise = null;

const FIREBASE_SDK = [
  'https://www.gstatic.com/firebasejs/8.10.1/firebase-app.js',
  'https://www.gstatic.com/firebasejs/8.10.1/firebase-auth.js',
  'https://www.gstatic.com/firebasejs/8.10.1/firebase-firestore.js'
];

function loadScript(src) {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = src;
    script.onload = resolve;
    script.onerror = () => reject(new Error(`Failed to load ${src}`));
    document.head.appendChild(script);
  });
}

// Loads the Firebase SDK on demand and signs in anonymously. Safe to call
// repeatedly: concurrent and later calls share one in-flight promise, and a
// failure clears it so the next call can retry.
function initFirebase() {
  if (!initPromise) {
    initPromise = (async () => {
      if (!window.firebase) {
        for (const src of FIREBASE_SDK) await loadScript(src); // app must load first
      }
      app = firebase.apps.length ? firebase.app() : firebase.initializeApp(firebaseConfig);
      db = firebase.firestore();
      auth = firebase.auth();
      await auth.signInAnonymously();
      user = auth.currentUser;
      return user;
    })().catch(err => {
      initPromise = null;
      throw err;
    });
  }
  return initPromise;
}

// --- Lobby Code Generation ---
function generateLobbyCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let code = '';
  for (let i = 0; i < 6; i++) code += chars.charAt(Math.floor(Math.random() * chars.length));
  return code;
}

// --- Create Lobby ---
async function createLobby(selectedMode) {
  let code, ref, exists;
  try {
    do {
      code = generateLobbyCode();
      ref = db.collection('games').doc(code);
      exists = (await ref.get()).exists;
    } while (exists);
    console.log('Creating lobby with code:', code, 'mode:', selectedMode, 'user:', user && user.uid);
    await ref.set({
      players: { X: user.uid, O: null },
      board: Array(9).fill(""),
      moveHistory: { X: [], O: [] },
      blockedCell: null,
      currentTurn: "X",
      status: "waiting",
      mode: selectedMode,
      created: firebase.firestore.FieldValue.serverTimestamp()
    });
    console.log('Lobby created!');
    return code;
  } catch (e) {
    console.error('Error in createLobby:', e);
    throw e;
  }
}

// --- Join Lobby ---
async function joinLobby(code) {
  const ref = db.collection('games').doc(code);
  const snap = await ref.get();
  if (!snap.exists) throw new Error("Lobby not found");
  const data = snap.data();
  if (data.players.O && data.players.O !== user.uid) throw new Error("Lobby full");
  if (!data.players.O) {
    await ref.update({
      'players.O': user.uid,
      status: "in_progress"
    });
  }
  return data;
}

// --- Listen to Game State ---
function listenToGame(code, callback) {
  return db.collection('games').doc(code).onSnapshot(doc => {
    if (doc.exists) callback(doc.data());
  });
}

// --- Make Move ---
async function makeMove(code, idx, value) {
  const ref = db.collection('games').doc(code);
  return db.runTransaction(async tx => {
    const doc = await tx.get(ref);
    if (!doc.exists) throw new Error("Game not found");
    const data = doc.data();
    if (data.status !== "in_progress") throw new Error("Game not active");
    if (data.currentTurn !== value) throw new Error("Not your turn");
    if (data.board[idx]) throw new Error("Cell occupied");

    // Ensure blocked cell remains locked
    if (data.mode === 'luck' && data.blockedCell === idx) throw new Error("Cell blocked");

    // Update board and move history
    const newBoard = data.board.slice();
    newBoard[idx] = value;

    const newMoveHistory = {
      X: [...(data.moveHistory?.X || [])],
      O: [...(data.moveHistory?.O || [])]
    };
    newMoveHistory[value].push(idx);

    let nextTurn = value === "X" ? "O" : "X";
    let status = "in_progress";
    let winner = null;
    let winningCombo = null;
    let blockedCell = data.blockedCell === undefined ? null : data.blockedCell;

    // Apply rotation rules
    if (data.mode !== 'classic') {
      if (newMoveHistory[value].length > 3) {
        const oldest = newMoveHistory[value].shift();
        newBoard[oldest] = "";
      }
    }

    // Apply luck mode cell blocking
    if (data.mode === 'luck' && blockedCell === null && newMoveHistory.X.length + newMoveHistory.O.length === 6) {
      let open = newBoard.map((v, i) => v === "" ? i : null).filter(i => i !== null);
      if (open.length) {
        blockedCell = open[Math.floor(Math.random() * open.length)];
      }
    }

    // Check win condition
    const winCombos = [
      [0, 1, 2], [3, 4, 5], [6, 7, 8], // rows
      [0, 3, 6], [1, 4, 7], [2, 5, 8], // cols
      [0, 4, 8], [2, 4, 6]           // diags
    ];

    for (const combo of winCombos) {
      const [a, b, c] = combo;
      if (newBoard[a] && newBoard[a] === newBoard[b] && newBoard[a] === newBoard[c]) {
        winner = newBoard[a];
        winningCombo = combo;
        status = "finished";
        break;
      }
    }

    // Check draw
    if (!winner) {
      let allFilled = true;
      for (let i = 0; i < 9; i++) { // board is 0 to 8
        if (!newBoard[i] && !(data.mode === 'luck' && blockedCell === i)) {
          allFilled = false;
          break;
        }
      }
      if (allFilled) {
        status = "finished";
      }
    }

    tx.update(ref, {
      board: newBoard,
      moveHistory: newMoveHistory,
      blockedCell: blockedCell,
      currentTurn: nextTurn,
      status: status,
      ...(winner && { winner, winningCombo })
    });
  });
}

// --- Handle Game Abandonment ---
async function abandonGame(code, playerRole) {
  if (!code) return false;

  try {
    const ref = db.collection('games').doc(code);
    const doc = await ref.get();

    if (!doc.exists) return false;

    await ref.update({
      status: 'abandoned',
      abandonedBy: playerRole,
      lastUpdated: firebase.firestore.FieldValue.serverTimestamp()
    });

    return true;
  } catch (error) {
    console.error('Error abandoning game:', error);
    return false;
  }
}

// --- Exported API ---
window.X3O3Multiplayer = {
  initFirebase,
  createLobby,
  joinLobby,
  listenToGame,
  makeMove,
  abandonGame,
  getUser: () => user
};
